'use client';

import { useRef, type CSSProperties, type ReactNode } from 'react';
import { usePlayback } from './use-playback';
import './gradient-mesh-drift.css';

export interface GradientMeshDriftProps {
  /** Four colors for the drifting fields. */
  palette: [string, string, string, string];
  children: ReactNode;
  paused?: boolean;
  className?: string;
}

/**
 * Four soft color fields drift slowly behind a panel. The foreground sits on
 * a solid card for contrast. The drift pauses off screen, in a hidden tab
 * or when paused, and is still with reduced motion.
 */
export function GradientMeshDrift({
  palette,
  children,
  paused = false,
  className = '',
}: GradientMeshDriftProps) {
  const root = useRef<HTMLDivElement>(null);
  const playing = usePlayback(root, paused);
  return (
    <div
      ref={root}
      className={`mg-mesh ${className}`}
      data-playing={playing}
      style={palette.reduce(
        (s, c, i) => ({ ...s, [`--mg-c${i + 1}`]: c }),
        {} as CSSProperties
      )}
    >
      <span className='mg-mesh__blob mg-mesh__blob--1' aria-hidden='true' />
      <span className='mg-mesh__blob mg-mesh__blob--2' aria-hidden='true' />
      <span className='mg-mesh__blob mg-mesh__blob--3' aria-hidden='true' />
      <span className='mg-mesh__blob mg-mesh__blob--4' aria-hidden='true' />
      <div className='mg-mesh__panel'>{children}</div>
    </div>
  );
}

.mg-mesh {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 220px;
  overflow: hidden;
  padding: 24px;
  border-radius: 16px;
  background: var(--mg-c1);
  isolation: isolate;
  transition: background-color 600ms ease;
}

.mg-mesh__blob {
  position: absolute;
  z-index: -1;
  width: 70%;
  aspect-ratio: 1;
  border-radius: 50%;
  filter: blur(36px);
  opacity: 0.85;
  animation: mg-mesh-drift 14s ease-in-out infinite alternate;
  animation-play-state: paused;
  transition: background-color 600ms ease;
}

.mg-mesh[data-playing='true'] .mg-mesh__blob {
  animation-play-state: running;
}

.mg-mesh__blob--1 {
  top: -20%;
  left: -15%;
  background: var(--mg-c2);
}

.mg-mesh__blob--2 {
  right: -20%;
  bottom: -25%;
  background: var(--mg-c3);
  animation-delay: -4s;
}

.mg-mesh__blob--3 {
  top: 10%;
  right: -10%;
  width: 45%;
  background: var(--mg-c4);
  animation-delay: -8s;
}

.mg-mesh__blob--4 {
  bottom: -15%;
  left: 10%;
  width: 40%;
  background: var(--mg-c2);
  animation-delay: -11s;
}

.mg-mesh__panel {
  max-width: 260px;
  padding: 18px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 12px 30px -18px rgba(12, 23, 56, 0.6);
  color: var(--mg-ink, #0c1738);
}

@keyframes mg-mesh-drift {
  to {
    transform: translate(30%, 18%) scale(1.15);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-mesh__blob {
    animation: none;
  }
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * Whether a continuous effect should run: its element is on screen, the
 * browser tab is visible and the caller has not paused it. Loops should stop
 * (or set `animation-play-state: paused`) whenever this returns false.
 */
export function usePlayback(
  ref: RefObject<Element | null>,
  paused = false
): boolean {
  const [onScreen, setOnScreen] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') {
      setOnScreen(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setOnScreen(entry.isIntersecting)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== 'hidden');
    update();
    document.addEventListener('visibilitychange', update);
    return () => document.removeEventListener('visibilitychange', update);
  }, []);

  return onScreen && pageVisible && !paused;
}
